import "server-only";
import {randomUUID} from "node:crypto";import {and,asc,eq,inArray,sql} from "drizzle-orm";import {db} from "@/db";import {attemptAnswers,fullMockAnswers,practiceSessionQuestions,practiceSessions,questionOptions,questionSolutions,rankedChallengeItems,rankedChallengeRuns,rankedChallenges} from "@/db/schema";import {awardCompletedLearning} from "@/lib/gamification/award";import type{ChallengeType}from "@/lib/gamification/catalog";import{getSafeSessionContent}from "@/lib/practice/queries";import{CHALLENGE_POLICY,challengePhase}from "./policy";
type Tx=Parameters<Parameters<typeof db.transaction>[0]>[0];export type StartChallengeResult={ok:true;runId:string;resumed:boolean}|{ok:false;reason:"NOT_FOUND"|"NOT_LIVE"|"CANCELLED"|"CHALLENGE_START_WINDOW_CLOSED"|"INVALID_FORM"};
type Task16TestHooks={afterStartWork?:()=>void|Promise<void>;afterFinalizeWork?:()=>void|Promise<void>};let task16TestHooks:Task16TestHooks|undefined;
export function installTask16TestHooks(hooks:Task16TestHooks|undefined){if(process.env.NODE_ENV==="production"||process.env.TASK16_TEST_MODE!=="true")throw new Error("TASK16_TEST_HOOKS_DISABLED");task16TestHooks=hooks;}
export async function startRankedChallenge(challengeId:string,userId:string,now=new Date()):Promise<StartChallengeResult>{return db.transaction(async tx=>{await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${`${challengeId}:${userId}:ranked-start`},0))`);const[old]=await tx.select().from(rankedChallengeRuns).where(and(eq(rankedChallengeRuns.challengeId,challengeId),eq(rankedChallengeRuns.userId,userId))).limit(1);if(old)return{ok:true,runId:old.id,resumed:true};const[c]=await tx.select().from(rankedChallenges).where(eq(rankedChallenges.id,challengeId)).for("share").limit(1);if(!c)return{ok:false,reason:"NOT_FOUND"};if(c.status==="CANCELLED")return{ok:false,reason:"CANCELLED"};if(challengePhase(c,now)!=="LIVE"||!c.endsAt)return{ok:false,reason:"NOT_LIVE"};const policy=CHALLENGE_POLICY[c.type as ChallengeType];if(c.endsAt.getTime()-now.getTime()<policy.durationMs)return{ok:false,reason:"CHALLENGE_START_WINDOW_CLOSED"};const items=await tx.select().from(rankedChallengeItems).where(eq(rankedChallengeItems.challengeId,c.id)).orderBy(asc(rankedChallengeItems.position));if(items.length!==policy.questions)return{ok:false,reason:"INVALID_FORM"};const runId=randomUUID();const section=c.type==="READING_100"?"READING":"LISTENING";const listeningDeadline=section==="LISTENING"?new Date(now.getTime()+45*60_000):null;const readingDeadline=section==="READING"?new Date(now.getTime()+75*60_000):null;await tx.insert(rankedChallengeRuns).values({id:runId,challengeId:c.id,userId,status:"IN_PROGRESS",section,listeningDeadline,readingDeadline,startedAt:now});for(const part of policy.parts){const partItems=items.filter(i=>i.part===part);const[s]=await tx.insert(practiceSessions).values({userId,skillArea:part<=4?"LISTENING":"READING",practiceType:`ranked_part_${part}`,part,status:"in_progress",questionCount:partItems.length,requestedQuestionCount:partItems.length,source:"ranked_challenge",rankedChallengeRunId:runId,rankedChallengeOrder:part}).returning({id:practiceSessions.id});await tx.insert(practiceSessionQuestions).values(partItems.map((i,x)=>({sessionId:s.id,questionId:i.questionId,displayOrder:x+1,passageSetId:i.groupId})));}await task16TestHooks?.afterStartWork?.();return{ok:true,runId,resumed:false};});}
export async function getRankedRun(runId:string,userId:string){const[row]=await db.select({run:rankedChallengeRuns,challenge:rankedChallenges}).from(rankedChallengeRuns).innerJoin(rankedChallenges,eq(rankedChallenges.id,rankedChallengeRuns.challengeId)).where(and(eq(rankedChallengeRuns.id,runId),eq(rankedChallengeRuns.userId,userId))).limit(1);if(!row)return null;const sessions=await db.select().from(practiceSessions).where(eq(practiceSessions.rankedChallengeRunId,runId)).orderBy(asc(practiceSessions.rankedChallengeOrder));return{...row,sessions};}
export async function getRankedAttemptContent(runId:string,userId:string,now=new Date()){const data=await getRankedRun(runId,userId);if(!data||data.run.status!=="IN_PROGRESS")return null;const deadline=data.run.section==="LISTENING"?data.run.listeningDeadline:data.run.readingDeadline;if(!deadline)return null;const sessions=data.sessions.filter(s=>s.skillArea===data.run.section);const content=await Promise.all(sessions.map(async session=>{const safe=await getSafeSessionContent(session.id,session.skillArea==="LISTENING");const answers=await db.select({questionId:fullMockAnswers.questionId,selectedOptionId:fullMockAnswers.selectedOptionId}).from(fullMockAnswers).where(eq(fullMockAnswers.sessionId,session.id));return{session,questions:safe.questions,groups:safe.groups,answers:Object.fromEntries(answers.map(a=>[a.questionId,a.selectedOptionId]))};}));return{run:data.run,challenge:data.challenge,deadline:deadline.toISOString(),expired:deadline<=now,sessions:content};}
export async function saveRankedAnswer(input:{runId:string;sessionId:string;questionId:string;optionId:string;userId:string;now?:Date}){return db.transaction(async tx=>{const now=input.now??new Date();const[row]=await tx.select({run:rankedChallengeRuns,session:practiceSessions}).from(practiceSessions).innerJoin(rankedChallengeRuns,eq(rankedChallengeRuns.id,practiceSessions.rankedChallengeRunId)).where(and(eq(rankedChallengeRuns.id,input.runId),eq(rankedChallengeRuns.userId,input.userId),eq(practiceSessions.id,input.sessionId))).for("update").limit(1);if(!row||row.run.status!=="IN_PROGRESS"||row.run.section!==row.session.skillArea)return{ok:false as const,reason:"LOCKED" as const};const deadline=row.run.section==="LISTENING"?row.run.listeningDeadline:row.run.readingDeadline;if(!deadline||deadline<=now)return{ok:false as const,reason:"EXPIRED" as const};const[[assigned],[option]]=await Promise.all([tx.select().from(practiceSessionQuestions).where(and(eq(practiceSessionQuestions.sessionId,input.sessionId),eq(practiceSessionQuestions.questionId,input.questionId))).limit(1),tx.select().from(questionOptions).where(and(eq(questionOptions.id,input.optionId),eq(questionOptions.questionId,input.questionId))).limit(1)]);if(!assigned||!option)return{ok:false as const,reason:"INVALID" as const};await tx.insert(fullMockAnswers).values({sessionId:input.sessionId,userId:input.userId,questionId:input.questionId,selectedOptionId:input.optionId}).onConflictDoUpdate({target:[fullMockAnswers.sessionId,fullMockAnswers.questionId],set:{selectedOptionId:input.optionId,updatedAt:now}});return{ok:true as const};});}
async function scoreArea(tx:Tx,runId:string,userId:string,area:"LISTENING"|"READING",now:Date){const sessions=await tx.select().from(practiceSessions).where(and(eq(practiceSessions.rankedChallengeRunId,runId),eq(practiceSessions.skillArea,area)));let correct=0,total=0;for(const s of sessions){if(s.status==="submitted"){correct+=s.scoreCorrect??0;total+=s.scoreTotal??0;continue;}const assigned=await tx.select().from(practiceSessionQuestions).where(eq(practiceSessionQuestions.sessionId,s.id));const ids=assigned.map(a=>a.questionId);const[saved,solutions]=await Promise.all([tx.select().from(fullMockAnswers).where(eq(fullMockAnswers.sessionId,s.id)),tx.select().from(questionSolutions).where(inArray(questionSolutions.questionId,ids))]);const selected=new Map(saved.map(a=>[a.questionId,a.selectedOptionId]));const keys=new Map(solutions.map(x=>[x.questionId,x.correctOptionId]));const rows=assigned.map(a=>({sessionId:s.id,userId,questionId:a.questionId,selectedOptionId:selected.get(a.questionId)??null,isCorrect:selected.get(a.questionId)===keys.get(a.questionId),answeredAt:null}));await tx.insert(attemptAnswers).values(rows).onConflictDoNothing();const c=rows.filter(x=>x.isCorrect).length;correct+=c;total+=rows.length;await tx.update(practiceSessions).set({status:"submitted",submittedAt:now,scoreCorrect:c,scoreTotal:rows.length,submissionReason:"ranked_section_complete"}).where(eq(practiceSessions.id,s.id));}return{correct,total};}
export async function finalizeRankedSection(runId:string,userId:string,expectedSection:"LISTENING"|"READING",now=new Date()){return db.transaction(async tx=>{await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${`${runId}:ranked-finalize`},0))`);const[run]=await tx.select().from(rankedChallengeRuns).where(and(eq(rankedChallengeRuns.id,runId),eq(rankedChallengeRuns.userId,userId))).for("update").limit(1);if(!run)return{ok:false as const};if(run.status==="COMPLETED")return{ok:true as const,status:"COMPLETED" as const};if(run.section!==expectedSection)return{ok:true as const,status:run.section as "LISTENING"|"READING"};const[c]=await tx.select().from(rankedChallenges).where(eq(rankedChallenges.id,run.challengeId)).limit(1);if(!c)return{ok:false as const};if(run.section==="LISTENING"){const score=await scoreArea(tx,run.id,userId,"LISTENING",now);if(c.type==="FULL_200"){if(!run.listeningDeadline)return{ok:false as const};const deadline=new Date(run.listeningDeadline.getTime()+75*60_000);if(!c.endsAt||deadline>c.endsAt)throw new Error("INVALID_CHALLENGE_DEADLINE");await tx.update(rankedChallengeRuns).set({section:"READING",listeningScore:score.correct,readingDeadline:deadline,updatedAt:now}).where(eq(rankedChallengeRuns.id,run.id));await task16TestHooks?.afterFinalizeWork?.();return{ok:true as const,status:"READING" as const};}await complete(tx,run,c.type as ChallengeType,userId,score.correct,0,now);await task16TestHooks?.afterFinalizeWork?.();return{ok:true as const,status:"COMPLETED" as const};}if(run.section==="READING"){const score=await scoreArea(tx,run.id,userId,"READING",now);await complete(tx,run,c.type as ChallengeType,userId,run.listeningScore??0,score.correct,now);await task16TestHooks?.afterFinalizeWork?.();return{ok:true as const,status:"COMPLETED" as const};}return{ok:false as const};});}
async function complete(tx:Tx,run:typeof rankedChallengeRuns.$inferSelect,type:ChallengeType,userId:string,listening:number,reading:number,now:Date){const total=type==="LISTENING_100"?listening:type==="READING_100"?reading:listening+reading;const sessions=await tx.select({id:practiceSessions.id}).from(practiceSessions).where(eq(practiceSessions.rankedChallengeRunId,run.id));const ids=sessions.map(s=>s.id);const attempts=await tx.select().from(attemptAnswers).where(inArray(attemptAnswers.sessionId,ids));await awardCompletedLearning(tx,{userId,sourceType:"CHALLENGE_RUN",sourceId:run.id,questionIds:attempts.map(a=>a.questionId),completion:type});await tx.update(rankedChallengeRuns).set({status:"COMPLETED",section:null,listeningScore:listening,readingScore:reading,totalScore:total,completedAt:now,updatedAt:now}).where(eq(rankedChallengeRuns.id,run.id));await tx.delete(fullMockAnswers).where(inArray(fullMockAnswers.sessionId,ids));}
